export class Modal{constructor(){this.buttons=document.querySelectorAll("[data-modal-open]"),this.buttons.length&&(this.modal=document.querySelector("#lead-modal"),this.init())}init(){this.modal&&"function"==typeof this.modal.showModal?(this.buttons.forEach(t=>t.addEventListener("click",()=>{this.modal.showModal(),setTimeout(()=>this.modal.querySelector("[data-phone]").focus(),50)})),this.modal.querySelector("[data-modal-close]").addEventListener("click",()=>this.modal.close()),this.modal.addEventListener("click",t=>{t.target===this.modal&&this.modal.close()})):this.buttons.forEach(t=>t.addEventListener("click",()=>{location.href="/poverka-tatarstan/kontakty"}))}}